{
  "description": "The creature is a single quadrupedal animal shown in right-facing profile against a plain light background. Its ventral and lateral surfaces, head, and limbs are covered in dense shaggy brown fur like a bear, with a lighter tan muzzle and darker brown on the lower legs. Its dorsal surface from the top of the head to the tip of the rear is covered by a continuous glossy dark brown to black segmented exoskeleton that is smooth and reflective. The animal stands on four thick limbs with clawed paws and has a bear-like head with a snout, eyes, and nose, topped by a large curved horn arising from the exoskeleton on the head, and a narrow segmented pointed tail extending beyond the hindquarters.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like, elongated snout with a large black nose at the tip, brown eyes on the side of the face, light tan fur on the muzzle and around the mouth, dark whiskers, brown fur on the cheeks and forehead",
      "where": "at the anterior end of the body, facing to the right, partially capped dorsally by the glossy helmet"
    },
    {
      "part": "horns",
      "looks_like": "one single large glossy black horn, long and strongly curved, arising from the helmet on top of the head, arching forward then upward and backward to a sharp pointed tip, with a small triangular projection on the inner curve near the base",
      "where": "on the dorsal midline of the head, originating from the helmet between and in front of the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in fluffy brown fur, with visible inner fur",
      "where": "on top of the head behind the horn base, protruding through openings in the helmet"
    },
    {
      "part": "legs",
      "looks_like": "four thick, columnar limbs covered in dense long shaggy brown fur, muscular in appearance",
      "where": "two forelimbs under the chest/shoulder region and two hindlimbs under the rear/hip region, supporting the body vertically"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with visible dark curved claws on the toes, the fur extends to the paws",
      "where": "at the distal ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "one narrow, tapering, segmented tail with overlapping glossy dark rings ending in a sharp point",
      "where": "extending posteriorly from the rear of the dorsal shell beyond the furry hindquarters, angled slightly downward"
    },
    {
      "part": "shell",
      "looks_like": "a continuous glossy dark brown-black exoskeleton, smooth and highly reflective, appearing hard",
      "where": "covering the entire dorsal surface from the helmet on the head, around the neck, over the back, to the tail tip"
    },
    {
      "part": "plates",
      "looks_like": "multiple overlapping plates forming the shell: a helmet of 2-3 plates on the head, 3-4 concentric ridged rings around the neck and lower throat, a large smooth shoulder shield over the foreback, about 10-12 transverse band-like plates over the mid-back and rear, and two large oval smooth side shields",
      "where": "helmet on the head, rings encircling the neck, shoulder shield over the shoulders, transverse bands along the back, and oval shields on the lateral sides over the shoulder and hip joints"
    },
    {
      "part": "markings",
      "looks_like": "dense shaggy fur, medium brown over most of the body and limbs, lighter tan-beige on the muzzle and around the eyes, darker brown on the lower limbs, no spots or stripes",
      "where": "covering all exposed soft parts: head, neck, chest, belly, sides, and limbs"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "rhinoceros beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
